function sync(api){api.saveFiles()}
function addFile(api,name='Untitled.txt',content='',folder='Documents'){let unique=name;let n=2;while(api.files.some(f=>f.name===unique&&f.folder===folder))unique=name.replace(/(\.[^.]+)?$/,m=>` ${n++}${m}`);const file={id:uid(),name:unique,content,folder,updated:Date.now()};api.files.push(file);sync(api);return file}
function makeFiles(api){const root=document.createElement('div');root.className='oa-app';let folder='Home',selected=null,query='';const folders=['Home','Documents','Downloads'];let extraFolders=[];try{extraFolders=JSON.parse(localStorage.getItem('orbit-extra-folders')||'[]')}catch{}for(const f of api.files.map(f=>f.folder)){if(f&&!folders.includes(f)&&!extraFolders.includes(f))extraFolders.push(f)}
root.innerHTML=`<div class="oa-toolbar">${button('plus','New file','oa-btn-primary')}<div class="oa-file-actions">${button('upload','Import file')}${button('download','Download selected')}${button('trash','Delete selected')}</div><div class="oa-spacer"></div><label class="oa-search">${svg('search',14)}<input placeholder="Search files" aria-label="Search files"></label><input class="oa-file-upload" type="file" accept="text/*,.md,.json,.csv,.js,.html,.css" hidden multiple></div><div class="oa-body"><aside class="oa-sidebar"><div class="oa-side-label">Places</div><div class="oa-folders"></div></aside><main class="oa-files-content"><div class="oa-path"></div><div class="oa-file-list"></div><div class="oa-file-status"></div></main></div>`;
function render(){root.querySelector('.oa-folders').innerHTML=[...folders,...extraFolders].map(f=>`<button class="oa-folder ${folder===f?'active':''}" data-folder="${esc(f)}">${svg(f==='Home'?'home':'folder',17)}${esc(f)}</button>`).join('');root.querySelector('.oa-path').innerHTML=`${svg('home',14)} <span>My computer</span> ${svg('arrow',11)} <strong>${esc(folder)}</strong>`;const matches=api.files.filter(f=>(folder==='Home'||f.folder===folder)&&f.name.toLowerCase().includes(query.toLowerCase()));const list=root.querySelector('.oa-file-list');list.innerHTML=`<div class="oa-file-head"><span>Name</span><span>Modified</span><span>Size</span></div>`+matches.map(f=>`<div class="oa-file-row ${selected===f.id?'selected':''}" data-file="${esc(f.id)}" tabindex="0" role="button" aria-label="Open ${esc(f.name)}"><div class="oa-file-name">${svg('file',22)}<span>${esc(f.name)}</span></div><span class="oa-muted">${new Date(f.updated||Date.now()).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span><span class="oa-muted">${formatSize(new Blob([f.content||'']).size)}</span></div>`).join('')+(!matches.length?`<div class="oa-empty">${svg('folder',32)}<br>${query?'No files found.':'A little space for your next idea.'}<br><span style="font-size:11px">${query?'Try another search.':'Create a file or import one from your device.'}</span></div>`:'');root.querySelector('.oa-file-status').textContent=`${matches.length} item${matches.length===1?'':'s'} · Saved on this device`;root.querySelector('[aria-label="Download selected"]').disabled=!api.files.some(f=>f.id===selected);root.querySelector('[aria-label="Delete selected"]').disabled=!api.files.some(f=>f.id===selected)}
root.addEventListener('click',e=>{const place=e.target.closest('[data-folder]');if(place){folder=place.dataset.folder;selected=null;render()}const row=e.target.closest('[data-file]');if(row){selected=row.dataset.file;root.querySelectorAll('[data-file]').forEach(item=>item.classList.toggle('selected',item.dataset.file===selected));root.querySelector('[aria-label="Download selected"]').disabled=false;root.querySelector('[aria-label="Delete selected"]').disabled=false}});root.addEventListener('dblclick',e=>{const row=e.target.closest('[data-file]');if(row)api.openApp('notes',{fileId:row.dataset.file})});root.addEventListener('keydown',e=>{const row=e.target.closest('[data-file]');if(row&&e.key==='Enter'){e.preventDefault();api.openApp('notes',{fileId:row.dataset.file})}});
root.querySelector('[aria-label="New file"]').onclick=()=>{const f=addFile(api,'Untitled.txt','',folder==='Home'?'Documents':folder);selected=f.id;render();api.openApp('notes',{fileId:f.id})};root.querySelector('.oa-search input').oninput=e=>{query=e.target.value;render()};root.querySelector('[aria-label="Import file"]').onclick=()=>root.querySelector('.oa-file-upload').click();root.querySelector('.oa-file-upload').onchange=async e=>{for(const file of e.target.files){if(file.size>2*1024*1024){api.toast('Please choose text files under 2 MB.');continue}addFile(api,file.name,await file.text(),folder==='Home'?'Downloads':folder)}render();api.toast('Files imported');e.target.value=''};root.querySelector('[aria-label="Download selected"]').onclick=()=>{const file=api.files.find(f=>f.id===selected);if(!file)return;const url=URL.createObjectURL(new Blob([file.content||''],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);api.toast('File downloaded')};root.querySelector('[aria-label="Delete selected"]').onclick=()=>{const i=api.files.findIndex(f=>f.id===selected);if(i<0)return;const file=api.files[i];api.files.splice(i,1);selected=null;sync(api);render();api.toast(`${file.name} deleted`)};
const change=()=>{for(const f of api.files.map(f=>f.folder)){if(f&&!folders.includes(f)&&!extraFolders.includes(f))extraFolders.push(f)}render()};window.addEventListener('orbit-files-changed',change);render();return{element:root,title:'Files',destroy:()=>window.removeEventListener('orbit-files-changed',change)}}
function formatSize(n){return n<1024?`${n} B`:`${(n/1024).toFixed(1)} KB`}
function makeNotes(api){const root=document.createElement('div');root.className='oa-app';let active=api.files.find(f=>f.id===api.appOptions?.fileId)||api.files.find(f=>f.folder==='Documents')||api.files[0];if(!active)active=addFile(api,'Untitled.txt');root.innerHTML=`<div class="oa-toolbar">${button('plus','New note','oa-btn-primary')}<span class="oa-spacer"></span><span class="oa-muted oa-saved">All changes saved</span></div><div class="oa-body"><aside class="oa-notes-sidebar"></aside><main class="oa-note-editor"><input class="oa-note-title" aria-label="Note title" placeholder="Untitled"><div class="oa-note-date"></div><textarea class="oa-note-text" aria-label="Note content" placeholder="Make a little room for your thoughts…" spellcheck="true"></textarea><div class="oa-note-footer"><span class="oa-word-count"></span><span>Stored on this device</span></div></main></div>`;const title=root.querySelector('.oa-note-title'),body=root.querySelector('.oa-note-text');
function sidebar(){root.querySelector('.oa-notes-sidebar').innerHTML=api.files.map(f=>`<button class="oa-note-card ${active?.id===f.id?'active':''}" data-note="${esc(f.id)}"><strong>${esc(f.name.replace(/\.txt$/, ''))}</strong><small>${esc((f.content||'An empty page').slice(0,35).replace(/\n/g,' '))}</small></button>`).join('')}
function count(){const content=body.value.trim();root.querySelector('.oa-word-count').textContent=`${content?content.split(/\s+/).length:0} words · ${body.value.length} characters`}
function load(){title.disabled=!active;body.disabled=!active;if(!active){title.value='';body.value='';title.placeholder='No notes yet';body.placeholder='Create a new note to begin.';root.querySelector('.oa-note-date').textContent='';root.querySelector('.oa-saved').textContent='No note selected';sidebar();count();return}title.placeholder='Untitled';body.placeholder='Make a little room for your thoughts…';title.value=active.name.replace(/\.txt$/,'');body.value=active.content||'';root.querySelector('.oa-note-date').textContent=new Date(active.updated||Date.now()).toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'});root.querySelector('.oa-saved').textContent='All changes saved';sidebar();count()}
let savedTimer;function save(){if(!active)return;const raw=title.value.trim()||'Untitled';active.name=/\.[a-z0-9]{1,8}$/i.test(raw)?raw:raw+'.txt';active.content=body.value;active.updated=Date.now();api.saveFiles();root.querySelector('.oa-saved').textContent='Saving…';clearTimeout(savedTimer);savedTimer=setTimeout(()=>{root.querySelector('.oa-saved').textContent='All changes saved'},500);count();sidebar()}
title.oninput=save;body.oninput=save;root.querySelector('[aria-label="New note"]').onclick=()=>{active=addFile(api);load();title.focus();title.select()};root.querySelector('.oa-notes-sidebar').onclick=e=>{const b=e.target.closest('[data-note]');if(!b)return;active=api.files.find(f=>f.id===b.dataset.note);load()};const change=()=>{const existing=api.files.find(f=>f.id===active?.id);if(!existing){active=api.files[0];load()}else{active=existing;if(document.activeElement!==title&&document.activeElement!==body)load();else sidebar()}};window.addEventListener('orbit-files-changed',change);load();return{element:root,title:'Notes',onFocus:()=>{active=api.files.find(f=>f.id===active?.id)||api.files[0];load();if(active)body.focus()},destroy:()=>{clearTimeout(savedTimer);window.removeEventListener('orbit-files-changed',change)}}}
function tokenize(text){return(text.match(/(?:[^\s"']+|"[^"]*"|'[^']*')+/g)||[]).map(s=>s.replace(/^(["'])(.*)\1$/,'$2'))}
function makeTerminal(api){const root=document.createElement('div');root.className='oa-app oa-terminal';root.innerHTML=`<div class="oa-term-welcome"><div class="oa-term-brand">◒ ORBIT SHELL</div>Version 1.0 · Your little corner of the internet<br>Type <span style="color:#b4c8b4">help</span> to see what you can do.</div><div class="oa-terminal-output" role="log" aria-live="polite"></div><form class="oa-term-inputline"><span class="oa-term-prompt">guest@orbit ~ %</span><input class="oa-term-input" aria-label="Terminal command" autocomplete="off" spellcheck="false" autocapitalize="off"></form>`;const output=root.querySelector('.oa-terminal-output'),input=root.querySelector('input');let cwd='Home',history=[],historyIndex=0;const print=(str,cls='')=>{const line=document.createElement('div');line.textContent=str;if(cls)line.className=cls;output.append(line)};
function run(command){const [cmd,...args]=tokenize(command),arg=args.join(' ');const listed=()=>api.files.filter(f=>cwd==='Home'||f.folder===cwd);const find=name=>listed().find(f=>f.name===name)||api.files.find(f=>f.name===name);const commands={help:()=>print('A small shell, made for this desktop.\n\n  help               Show commands\n  ls                 List files\n  pwd                Show current folder\n  cd <folder>        Change folder (or cd ~)\n  cat <file>         Read a file\n  echo <text>        Print something\n  echo <text> > file Save text to a file\n  touch <file>       Create an empty file\n  mkdir <folder>     Create a folder\n  open <app|file>    Open an app or text file\n  date               Show date and time\n  neofetch           Meet your computer\n  whoami             Your local username\n  clear              Clear the terminal\n\nTip: use quotes around names with spaces. ↑ ↓ browse history.'),ls:()=>{let extras=[];try{extras=JSON.parse(localStorage.getItem('orbit-extra-folders')||'[]')}catch{}print((cwd==='Home'?['Documents/','Downloads/',...extras.map(f=>f+'/')]:[]).concat(listed().map(f=>f.name)).join('   ')||'This folder is empty.')},pwd:()=>print('/home/guest'+(cwd==='Home'?'':'/'+cwd)),cd:()=>{let extras=[];try{extras=JSON.parse(localStorage.getItem('orbit-extra-folders')||'[]')}catch{}const name=arg.replace(/^~\/?/,'').replace(/^\/home\/guest\/?/,'').replace(/\/$/,'');if(['','..','Home'].includes(name))cwd='Home';else if(['Documents','Downloads',...extras,...api.files.map(f=>f.folder)].includes(name))cwd=name;else print(`cd: ${arg}: folder not found`,'oa-term-error');root.querySelector('.oa-term-prompt').textContent=`guest@orbit ${cwd==='Home'?'~':cwd} %`},cat:()=>{const f=find(arg);print(f?f.content||'(empty file)':`cat: ${arg||'missing filename'}: file not found`,f?'':'oa-term-error')},echo:()=>{const mark=args.indexOf('>');if(mark>=0&&args[mark+1]){const name=args.slice(mark+1).join(' '),content=args.slice(0,mark).join(' ');let file=find(name);if(file){file.content=content;file.updated=Date.now();sync(api)}else addFile(api,name,content,cwd==='Home'?'Documents':cwd)}else print(arg)},touch:()=>{if(!arg)return print('Usage: touch <filename>','oa-term-error');if(!find(arg))addFile(api,arg,'',cwd==='Home'?'Documents':cwd)},mkdir:()=>{if(!arg||/[\/\\]/.test(arg))return print('Usage: mkdir <folder-name>','oa-term-error');let extras=[];try{extras=JSON.parse(localStorage.getItem('orbit-extra-folders')||'[]')}catch{}if(['Home','Documents','Downloads',...extras].includes(arg))return print('Folder already exists.','oa-term-error');extras.push(arg);localStorage.setItem('orbit-extra-folders',JSON.stringify(extras));window.dispatchEvent(new Event('orbit-files-changed'));print(`Created ${arg}/`)},open:()=>{const aliases={finder:'files',files:'files',notes:'notes',terminal:'terminal',calculator:'calculator',calc:'calculator',settings:'settings',about:'welcome',welcome:'welcome'};if(aliases[arg.toLowerCase()])api.openApp(aliases[arg.toLowerCase()]);else{const f=find(arg);if(f)api.openApp('notes',{fileId:f.id});else print(`open: ${arg||'missing app or filename'}: not found`,'oa-term-error')}},date:()=>print(new Date().toLocaleString(undefined,{dateStyle:'full',timeStyle:'long'})),whoami:()=>print('guest'),neofetch:()=>print('          .--.       guest@orbit\n       .-(    )-.     ───────────\n      (   ◒    )     OS       Orbit OS 1.0\n       `-(  )-´      Host     Your browser\n          ~~         Shell    Orbit Shell\n                     Storage  Local to this device\n                     Files    '+api.files.length+' little possibilities'),clear:()=>{output.replaceChildren();root.querySelector('.oa-term-welcome').hidden=true},uname:()=>print('Orbit OS 1.0 · Browser desktop'),exit:()=>print('You are already home. Close this window whenever you like.')};if(!cmd)return;if(commands[cmd]){try{commands[cmd]()}catch(err){print('Could not complete that command. Check browser storage is available.','oa-term-error')}}else print(`${cmd}: command not found. Try help.`,'oa-term-error')}
root.querySelector('form').onsubmit=e=>{e.preventDefault();const command=input.value.trim();if(!command)return;print(`${root.querySelector('.oa-term-prompt').textContent} ${command}`,'oa-term-command');history.push(command);historyIndex=history.length;input.value='';run(command);root.scrollTop=root.scrollHeight};input.onkeydown=e=>{if(e.key==='ArrowUp'){e.preventDefault();historyIndex=Math.max(0,historyIndex-1);input.value=history[historyIndex]||''}if(e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.min(history.length,historyIndex+1);input.value=history[historyIndex]||''}if(e.ctrlKey&&e.key==='l'){e.preventDefault();output.replaceChildren();root.querySelector('.oa-term-welcome').hidden=true}};root.addEventListener('click',e=>{if(!window.getSelection()?.toString())input.focus()});return{element:root,title:'Terminal',onFocus:()=>input.focus()}}
function calculate(expression){const tokens=expression.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').match(/(?:\d+\.?\d*|\.\d+)|[+\-*/%()]/g);if(!tokens||tokens.join('')!==expression.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/\s/g,''))throw Error('Invalid');let at=0;function atom(){let token=tokens[at++];if(token==='-')return-atom();if(token==='+')return atom();if(token==='('){const n=sum();if(tokens[at++]!==')')throw Error('Missing bracket');return n}if(!/^(\d+\.?\d*|\.\d+)$/.test(token||''))throw Error('Number expected');let n=Number(token);while(tokens[at]==='%'){at++;n/=100}return n}function product(){let n=atom();while(tokens[at]==='*'||tokens[at]==='/'){const op=tokens[at++],v=atom();n=op==='*'?n*v:n/v}return n}function sum(){let n=product();while(tokens[at]==='+'||tokens[at]==='-'){const op=tokens[at++],v=product();n=op==='+'?n+v:n-v}return n}const result=sum();if(at!==tokens.length||!Number.isFinite(result))throw Error('Cannot calculate');return String(Number(result.toPrecision(12)))}
function makeCalculator(){const root=document.createElement('div');root.className='oa-app oa-calc';let expression='',previous='',solved=false;root.innerHTML=`<div class="oa-calc-display"><div class="oa-calc-exp"></div><div class="oa-calc-number" aria-live="polite">0</div></div><div class="oa-calc-grid">${['AC','±','%','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','='].map(k=>`<button class="oa-calc-key ${['AC','±','%','÷','×','−','+'].includes(k)?'operator':''} ${k==='='?'equals':''} ${k==='0'?'zero':''}" data-key="${k}" aria-label="${({AC:'Clear','±':'Change sign','÷':'Divide','×':'Multiply','−':'Subtract','+':'Add','=':'Equals'})[k]||k}">${k}</button>`).join('')}</div>`;function render(){root.querySelector('.oa-calc-exp').textContent=previous;root.querySelector('.oa-calc-number').textContent=expression||'0'}function key(k){if(k==='AC'){expression='';previous='';solved=false}else if(k==='Backspace'){expression=expression.slice(0,-1);solved=false}else if(k==='='){if(!expression)return;try{previous=expression+' =';expression=calculate(expression);solved=true}catch{previous='Check your expression';expression='';solved=false}}else if(k==='±'){expression=expression.startsWith('−')?expression.slice(1):'−'+expression;solved=false}else{if(solved&&/[\d.]/.test(k)){expression='';previous=''}solved=false;if(expression.length<35){if(/[+−×÷]/.test(k)&&/[+−×÷]$/.test(expression))expression=expression.slice(0,-1)+k;else expression+=k}}render()}root.onclick=e=>{const b=e.target.closest('[data-key]');if(b)key(b.dataset.key)};root.tabIndex=-1;root.onkeydown=e=>{const map={'*':'×','/':'÷','-':'−',Enter:'=',Escape:'AC',Delete:'AC'};const k=map[e.key]||e.key;if(/^[0-9.+%()]$/.test(k)||['×','÷','−','=','AC','Backspace'].includes(k)){e.preventDefault();key(k)}};return{element:root,title:'Calculator',onFocus:()=>root.focus()}}
function makeSettings(api){const root=document.createElement('div');root.className='oa-app oa-settings';const palettes={aurora:{name:'Aurora',bg:'radial-gradient(ellipse at 25% 100%,#b9ddd2,transparent 65%),radial-gradient(ellipse at 80% 10%,#bfd8c6,transparent 65%),#e6e5cf'},dusk:{name:'Dusk',bg:'radial-gradient(ellipse at 22% 80%,#d2b7c8,transparent 60%),radial-gradient(ellipse at 90% 10%,#a1acc9,transparent 60%),#d6d4e1'},mint:{name:'Mint',bg:'radial-gradient(ellipse at 25% 100%,#97c6b7,transparent 65%),radial-gradient(ellipse at 85% 10%,#d8e4bc,transparent 65%),#ceddd0'}};root.innerHTML=`<h2>Make yourself at home.</h2><p>A little personalization goes a long way.</p><div class="oa-setting-heading">Desktop wallpaper</div><div class="oa-wallpapers">${Object.entries(palettes).map(([id,p])=>`<button class="oa-wallpaper ${api.wallpaper===id||(!api.wallpaper&&id==='aurora')?'active':''}" data-wallpaper="${id}" aria-label="${p.name} wallpaper"><div class="oa-wall-swatch" style="background:${p.bg}"><i>${svg('check',15)}</i></div><span>${p.name}</span></button>`).join('')}</div><div class="oa-setting-heading">About this computer</div><div class="oa-setting-row"><span>Operating system</span><strong>Orbit OS 1.0</strong></div><div class="oa-setting-row"><span>Workspace</span><strong>Your browser</strong></div><div class="oa-setting-row"><span>Storage</span><strong class="oa-storage-size"></strong></div><div class="oa-setting-row"><span>Keyboard shortcut</span><strong>⌘ / Ctrl + K · App launcher</strong></div><div class="oa-settings-about">Made for curious minds and open tabs.<br>Your files and preferences stay in this browser. Download anything you want to keep elsewhere.</div>`;const updateStorage=()=>{root.querySelector('.oa-storage-size').textContent=`${api.files.length} files · ${formatSize(new Blob([JSON.stringify(api.files)]).size)}`};updateStorage();window.addEventListener('orbit-files-changed',updateStorage);root.onclick=e=>{const b=e.target.closest('[data-wallpaper]');if(!b)return;api.setWallpaper(b.dataset.wallpaper);root.querySelectorAll('[data-wallpaper]').forEach(x=>x.classList.toggle('active',x===b));api.toast(`${palettes[b.dataset.wallpaper].name} wallpaper applied`)};return{element:root,title:'Settings',destroy:()=>window.removeEventListener('orbit-files-changed',updateStorage)}}
export function createApp(id,api){ensureStyles();if(id==='terminal')return makeTerminal(api);if(id==='files')return makeFiles(api);if(id==='notes')return makeNotes(api);if(id==='calculator')return makeCalculator(api);if(id==='settings')return makeSettings(api);const element=document.createElement('div');element.className='oa-app';element.innerHTML='<div class="oa-empty">This app is getting ready.</div>';return{element,title:id}}
